pub fn preset_tour(sim: SimId, preset_id: &str) -> &'static PresetTour {
    let list: &'static [PresetTour] = match sim {
        SimId::Blackhole => &TOURS_BLACKHOLE,
        SimId::Wormhole => &TOURS_WORMHOLE,
        SimId::BinaryBh => &TOURS_BINARY,
        SimId::WarpDrive => &TOURS_WARP,
        SimId::Supernova => &TOURS_SUPERNOVA,
        SimId::Pulsar => &TOURS_PULSAR,
        SimId::Starflight => &TOURS_STARFLIGHT,
        SimId::LensCluster => &TOURS_LENS_CLUSTER,
        SimId::Tde => &TOURS_TDE,
    };
    list.iter()
        .find(|t| t.preset_id == preset_id)
        .unwrap_or(&list[0])
}
